import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.CDpkVv68.js";const h=JSON.parse('{"title":"Equipment and loot","description":"","frontmatter":{},"headers":[],"relativePath":"game-design/equipment-and-loot.md","filePath":"game-design/equipment-and-loot.md"}'),r={name:"game-design/equipment-and-loot.md"};function i(s,e,l,d,p,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="equipment-and-loot" tabindex="-1">Equipment and loot <a class="header-anchor" href="#equipment-and-loot" aria-label="Permalink to &quot;Equipment and loot&quot;">​</a></h1><p><strong>Design status: Accepted direction; Proposed family roles and retention exceptions. Implementation: legacy items/durability/loot only.</strong></p><p>Favor replaceable, horizontal equipment and meaningful loss. Broad AOS-style insurance is not the chosen direction. A possible single Sacred Item retained through a priest system is <strong>not approved</strong>; priest roles and retention rules remain future design.</p><p>Legacy armor can protect two sides through one sleeves/leggings/gloves item while each limb has independent integrity. Shared durability belongs to that item. Hands contact and Arms contact are distinct; destroyed sleeves do not remove glove protection.</p><p>Proposed weapon identities include dagger precision, sword flexibility, mace/warhammer blunt force, axe cutting/equipment pressure and spear reach. These are directions, not final bonuses or balance.</p><p><strong>Gap:</strong> current legacy absorption/wear can support the first adapter, but materials, new loot rules and weapon-specific propagation are not implemented or part of Slice 0. Shield disability preserves ownership and existing death/loot.</p><h2 id="proposed-spellbook-exception" tabindex="-1">Proposed spellbook exception <a class="header-anchor" href="#proposed-spellbook-exception" aria-label="Permalink to &quot;Proposed spellbook exception&quot;">​</a></h2><p>The <a href="/Syrolands-Public/game-design/magic/spellbooks-scrolls-and-reagents.html#death-and-material-risk">magic material specification</a> protects permanently learned knowledge independently of physical loot and proposes that the baseline personal spellbook should not normally drop. Rare physical grimoires/manuscripts can be looted; scrolls and reagents are physical resources that generally drop on death. Exact personal representation/replacement, rare-book policies and prepared material value remain Unresolved. This does not approve broad insurance, Sacred Item retention, protected modifiers or a blessing mechanism. <a href="/Syrolands-Public/game-design/professions/inscription.html">Inscription</a> owns the proposed craft role; existing death handlers are unchanged.</p><h2 id="proposed-craft-quality-and-item-history" tabindex="-1">Proposed craft quality and item history <a class="header-anchor" href="#proposed-craft-quality-and-item-history" aria-label="Permalink to &quot;Proposed craft quality and item history&quot;">​</a></h2><p><a href="/Syrolands-Public/game-design/items/itemization-and-craft-quality.html">Itemization &amp; Craft Quality</a> owns Batch 01&#39;s shared crafted/drop quality language, envelopes, compact weapon dimensions, rare Masterworks, traits and latent resonance. <a href="/Syrolands-Public/game-design/professions/profession-system.html">Professions</a> owns production and reputation. These proposals preserve horizontal equipment and meaningful loss; no legacy item or current combat formula is changed.</p><p>Future Sacred/Resonant Sets concern synergy between compatible items, <strong>not</strong> approval of the separate Sacred Item retention proposal. Their scarcity, power, naming and loss behavior require <a href="/Syrolands-Public/game-design/items/itemization-and-craft-quality.html#open-questions-and-reconciliation">explicit reconciliation</a>.</p><h2 id="combat-foundation-cross-links" tabindex="-1">Combat foundation cross-links <a class="header-anchor" href="#combat-foundation-cross-links" aria-label="Permalink to &quot;Combat foundation cross-links&quot;">​</a></h2><p><a href="/Syrolands-Public/game-design/combat/weapons-and-damage.html">Weapon identities</a> and <a href="/Syrolands-Public/game-design/combat/armor-and-mitigation.html">armor/material/condition interactions</a> expand Proposed combat roles. Craft quality and maintenance must preserve the accepted loss/replaceability direction; Masterworks and special traits do not imply insurance. Exact penetration, trauma transmission and functional wear remain unresolved, with the experimental <a href="/Syrolands-Public/game-design/combat/damage.html">trauma policy</a> unchanged.</p>',13)])])}const u=a(r,[["render",i]]);export{h as __pageData,u as default};
